INSERT INTO projects (slug, num, title, tagline, year, image, role, tags, categories, stack, problem, impact, demo_link, github_link, featured, duration, metrics_performance, metrics_users, learnings, visual_bg, visual_label, created_at, updated_at) VALUES ('sita-bi', '01', 'SITA-BI Academic Portal', 'Sistem Informasi Tugas Akhir Jurusan Bahasa Inggris Politeknik Negeri Padang', 2025, '/sita-bi.webp', 'Full-Stack Developer', '["Full Stack","Education"]', '["fullstack"]', '["Next.js","Express.js","TypeScript","PostgreSQL","Docker","RESTful API"]', 'Jurusan Bahasa Inggris Politeknik Negeri Padang membutuhkan sistem terintegrasi untuk mengelola tugas akhir mahasiswa, mulai dari pengajuan proposal hingga sidang akhir.', '["Mengembangkan 204 API endpoint untuk mengelola seluruh proses tugas akhir","Membangun sistem dengan arsitektur monorepo menggunakan Express.js backend dan Next.js frontend","Mengimplementasikan fitur manajemen bimbingan, penilaian, dan penjadwalan sidang"]', 'https://sitabi.vercel.app', 'https://github.com/itsanla/sita-bi', 1, 'Ongoing', '204 API endpoints', 235, '["Monorepo architecture","Complex API design","Academic workflow automation","Docker containerization"]', 'linear-gradient(135deg,oklch(0.42 0.24 268) 0%,oklch(0.35 0.18 300) 100%)', 'Full Stack · Academic', datetime('now'), datetime('now'));
INSERT INTO projects (slug, num, title, tagline, year, image, role, tags, categories, stack, problem, impact, demo_link, github_link, featured, duration, metrics_performance, metrics_users, learnings, visual_bg, visual_label, created_at, updated_at) VALUES ('microservice-2025', '02', 'Microservices Architecture 2025', 'Enterprise-grade Microservices System dengan Kubernetes Orchestration', 2025, '/microservice.webp', 'DevOps & Backend Engineer', '["DevOps","Backend"]', '["backend","devops"]', '["Spring Boot","Kubernetes","AWS EC2","Docker","RabbitMQ","MongoDB","PostgreSQL","Prometheus","Grafana","ELK Stack"]', 'Membutuhkan sistem enterprise-grade dengan arsitektur microservices untuk Library Management dan E-Commerce Marketplace dengan skalabilitas tinggi.', '["Membangun 22 services yang berjalan dalam cluster Kubernetes dengan 16 URL endpoint","Mengimplementasikan CQRS pattern dengan event sourcing menggunakan H2 dan MongoDB","Mengelola infrastruktur 5 × AWS EC2 m7i.large dengan total 10 vCPU dan 40 GB RAM","Mengintegrasikan observability stack: Prometheus, Grafana, dan ELK Stack"]', 'https://microservice.dedyn.io', 'https://github.com/itsanla/microservice-2025', 1, '3 months', '22 microservices', 5, '["Kubernetes orchestration","CQRS pattern","Event-driven architecture","Cloud infrastructure management","Microservices monitoring"]', 'linear-gradient(135deg,oklch(0.25 0.12 240) 0%,oklch(0.20 0.08 200) 100%)', 'DevOps · Cloud', datetime('now'), datetime('now'));
INSERT INTO projects (slug, num, title, tagline, year, image, role, tags, categories, stack, problem, impact, demo_link, github_link, featured, duration, metrics_performance, metrics_users, learnings, visual_bg, visual_label, created_at, updated_at) VALUES ('vocalink-kmipn', '03', 'VocaLink — Juara 1 Nasional KMIPN VII 2025', 'Platform Bootcamp Berbasis AI Interaktif untuk Pengembangan Talenta Digital Indonesia', 2025, '/vocalink.webp', 'Team Lead & Full-Stack Developer', '["AI / ML","Full Stack"]', '["fullstack","ai"]', '["Next.js","TypeScript","TailwindCSS","AI/ML","IoT Integration"]', 'Indonesia membutuhkan platform bootcamp yang dapat mendukung pengembangan talenta digital menuju visi Indonesia Emas 2045 dengan pendekatan AI interaktif.', '["Meraih Juara 1 Nasional Kompetisi Inovasi Politeknik Nasional (KMIPN VII 2025) bidang Perencanaan Bisnis IoT","Mengembangkan platform bootcamp berbasis AI interaktif untuk meningkatkan kualitas pembelajaran","Berkontribusi dalam perencanaan bisnis dan pengembangan produk IoT terintegrasi"]', '', 'https://github.com/itsanla/3dpnp-kmipn2025', 1, '4 months', '1st Place National', 0, '["AI-powered education platforms","IoT business planning","National competition experience","Team leadership"]', 'linear-gradient(135deg,oklch(0.22 0.10 145) 0%,oklch(0.18 0.08 200) 100%)', 'AI/ML · Bootcamp', datetime('now'), datetime('now'));
INSERT INTO projects (slug, num, title, tagline, year, image, role, tags, categories, stack, problem, impact, demo_link, github_link, featured, duration, metrics_performance, metrics_users, learnings, visual_bg, visual_label, created_at, updated_at) VALUES ('pepsikuburger', '04', 'PEPSIKUBURGER — Platform Pemerintah', 'Platform Layanan Masyarakat DP3AP2KB Provinsi Sumatera Barat', 2025, '/pepsikuburger.webp', 'Project Manager & Full-Stack Developer', '["Government","Full Stack"]', '["fullstack"]', '["Laravel","Vue.js","MySQL","TailwindCSS","REST API"]', 'DP3AP2KB Sumatera Barat membutuhkan platform digital terintegrasi untuk pelayanan publik yang cepat, transparan, dan mendukung program pemberdayaan perempuan.', '["Memimpin tim 4 pengembang dalam pembuatan website resmi pemerintah","Melayani lebih dari 5.000 peserta perempuan dalam program pelatihan pemberdayaan ekonomi","Mengembangkan 11 fitur CRUD dan 16 tools interaktif untuk dashboard admin","Mengimplementasikan fitur pelaporan kasus kekerasan dan sistem pre-test/post-test pelatihan"]', 'https://agile-d3-2025.vercel.app', 'https://github.com/itsanla/AgileD3_2025', 1, '5 months', '5,000+ users served', 5000, '["Government platform development","Project management","Team coordination","Public service digitalization","Laravel + Vue.js integration"]', 'linear-gradient(135deg,oklch(0.42 0.24 268) 0%,oklch(0.35 0.18 300) 100%)', 'Full Stack · Gov Platform', datetime('now'), datetime('now'));
